package tv.vela.launcher;
import android.app.*;import android.os.*;import java.io.*;import java.util.*;import org.json.*;
/** Read-only diagnostic of the target app's public TV provider access. No tuning or database writes. */
public final class AntennaProbe extends Instrumentation {
 public void onCreate(Bundle args){super.onCreate(args);start();}
 public void onStart(){Bundle out=new Bundle();try{LiteAntennaData client=new LiteAntennaData(getTargetContext());CancellationSignal cancel=new CancellationSignal();List<LiveTvData.Channel> channels=client.channels(cancel);JSONArray rows=new JSONArray();for(LiveTvData.Channel c:channels)rows.put(new JSONObject().put("id",c.providerId).put("name",c.name).put("number",c.number).put("input",c.inputId).put("radio",c.radio).put("hd",c.hd).put("locked",c.locked));long now=System.currentTimeMillis()/1000;Map<String,List<LiveTvData.Programme>> guide=client.programmes(channels.subList(0,Math.min(6,channels.size())),now-1800,now+10800,cancel);int programmes=0;for(List<?> list:guide.values())programmes+=list.size();JSONObject report=new JSONObject().put("permitted",client.permitted()).put("channels",rows).put("programmes_first_six",programmes);File cached=new File(getTargetContext().getCacheDir(),"antenna-epg/programmes.db");report.put("xmltv_cache_bytes",cached.length());if(cached.isFile())try(android.database.sqlite.SQLiteDatabase db=android.database.sqlite.SQLiteDatabase.openDatabase(cached.getPath(),null,android.database.sqlite.SQLiteDatabase.OPEN_READONLY);android.database.Cursor count=db.rawQuery("SELECT COUNT(*) FROM programmes",null)){if(count.moveToFirst())report.put("xmltv_programmes",count.getInt(0));}try(FileOutputStream f=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"antenna-probe.json"))){f.write(report.toString(2).getBytes("UTF-8"));}out.putString("result","READ ONLY: "+channels.size()+" channels; "+programmes+" programmes for first six");}catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));}finish(out.containsKey("error")?1:-1,out);}
}
